/**
 帮我实现页面加载后通过store2用改文件的路径命名的namespace获取的数据
 该数据记录了socket的地址，和一个MarketList的列表。
 获取到该列表后要展示该列表，组件要单独分离出来，而不是在一个大的组件里嵌套生成子组件。
 socket链接后要发起请求，请求同步已有监听的Imarket.name的数据，同步后把已有的数据替换掉。
 不要删除该注释

 */
import { storeUtils } from '@fanfanlo';
import { ExpandLess, ExpandMore, InsertDriveFileOutlined as FileIcon } from '@mui/icons-material'; // Example icons
import {
    Box,
    Chip,
    CircularProgress, Collapse,
    Container,
    Divider,
    List, ListItem, ListItemText,
    Paper,
    Typography
} from '@mui/material';
import React, { useEffect, useRef, useState } from 'react';

// --- Interfaces (aligned with server + component needs) ---
interface IMarketFile {
    type: "js" | "css" | "html" | string; // Match server type, allow string for flexibility
    path: string;
    content: string; // This will hold the actual file content from WebSocket
}

interface IMarket {
    name: string;
    files: IMarketFile[];
    html?: string; // Optional: if you want to store/use the HTML from server
}

type MarketList = IMarket[];

interface IStoredData {
    socketAddr: string;
    marketList: { name: string }[]; // Store only names initially, content comes from WS
}

// Note: Duplicate comments and interface definitions removed for brevity

// --- MUI Component for Displaying Market File ---
interface MarketFileDisplayProps {
    file: IMarketFile;
}

const MarketFileDisplay: React.FC<MarketFileDisplayProps> = ({ file }) => {
    const [contentOpen, setContentOpen] = useState(false);

    const toggleContent = () => setContentOpen(!contentOpen);

    return (
        <>
            <ListItem sx={{ pl: 4, display: 'flex', alignItems: 'center' }}>
                 <FileIcon sx={{ mr: 1, fontSize: '1rem', flexShrink: 0 }} />
                 <ListItemText
                    primary={file.path}
                    secondary={`Type: ${file.type}`}
                    primaryTypographyProps={{ variant: 'body2', noWrap: true, flexGrow: 1, mr:1 }}
                    secondaryTypographyProps={{ variant: 'caption' }}
                 />
                 <Chip label={contentOpen ? 'Hide Content' : 'Show Content'} size="small" onClick={toggleContent} disabled={!file.content} data-testid={`MarketFileDisplay__toggleContentChip__01JFQX8K9Z__${file.path}`} />
            </ListItem>
            <Collapse in={contentOpen} timeout="auto" unmountOnExit>
                 <Box sx={{ pl: 6, pr: 2, pb: 1 }}>
                    <Paper elevation={1} sx={{ p: 1, maxHeight: '150px', overflowY: 'auto', background: '#f5f5f5' }}>
                        <Typography component="pre" variant="caption" sx={{ whiteSpace: 'pre-wrap', wordBreak: 'break-all' }}>
                            {file.content || '(Content not loaded or empty)'}
                        </Typography>
                    </Paper>
                 </Box>
            </Collapse>
        </>
    );
};


// --- MUI Component for Displaying Market Item ---
interface MarketItemDisplayProps {
    market: IMarket;
}

const MarketItemDisplay: React.FC<MarketItemDisplayProps> = ({ market }) => {
    const [open, setOpen] = useState(true);

    const handleClick = () => {
        setOpen(!open);
    };

    return (
        <>
            <ListItem button onClick={handleClick} data-testid={`MarketItemDisplay__marketItem__01JFQX8KA0__${market.name}`}>
                <ListItemText primary={market.name} primaryTypographyProps={{ fontWeight: 'bold' }} />
                {/* Always show expand icon if files array exists, even if empty initially */} 
                {market.files ? (open ? <ExpandLess /> : <ExpandMore />) : null} 
            </ListItem>
            {/* Render Collapse if market.files array exists */} 
            {market.files && (
                 <Collapse in={open} timeout="auto" unmountOnExit>
                    <List component="div" disablePadding>
                        {market.files.length > 0 ? (
                            market.files.map((file, index) => (
                                // Use a more specific key including path
                                <MarketFileDisplay key={`${market.name}-file-${index}-${file.path}`} file={file} />
                            ))
                        ) : (
                             <ListItem sx={{ pl: 4 }}>
                                <ListItemText primary="(Waiting for file data...)" primaryTypographyProps={{ fontStyle: 'italic', variant: 'body2' }}/>
                             </ListItem>
                        )}
                    </List>
                 </Collapse>
            )}
        </>
    );
};


// --- MUI Component for Displaying Market List ---
interface MarketListDisplayProps {
    marketList: MarketList;
    isLoading: boolean; 
}

const MarketListDisplay: React.FC<MarketListDisplayProps> = ({ marketList, isLoading }) => {
    if (isLoading) {
        return (
            <Box sx={{ display: 'flex', justifyContent: 'center', my: 3 }}>
                <CircularProgress />
            </Box>
        );
    }

    if (!marketList || marketList.length === 0) {
        return <Typography sx={{ mt: 2, fontStyle: 'italic' }}>No markets configured or found.</Typography>;
    }

    return (
        <Paper elevation={2} sx={{ mt: 2 }}>
             <List component="nav" aria-labelledby="nested-list-subheader">
                {marketList.map((market) => (
                    <MarketItemDisplay key={market.name} market={market} />
                ))}
            </List>
        </Paper>
    );
};


// --- Main MUI Component ---

const STORE_NAMESPACE = 'listen-editing-market';

export function ListenEditingMarkets() {
    const [socketAddr, setSocketAddr] = useState<string | null>("ws://localhost:8080");
    const [marketList, setMarketList] = useState<MarketList>([]); 
    const [isConnected, setIsConnected] = useState<boolean>(false);
    const [isLoading, setIsLoading] = useState<boolean>(true); 
    const ws = useRef<WebSocket | null>(null);
    const initialMarketNames = useRef<string[]>([]);

    // 1. Fetch initial config from store2
    useEffect(() => {
        setIsLoading(true);
        // const marketStore = store.namespace(STORE_NAMESPACE);
        const marketStore = storeUtils.namespace(STORE_NAMESPACE);
        const storedData = marketStore.read('marketData') as IStoredData | null;

        if (storedData) {
            console.log(`[${STORE_NAMESPACE}] Fetched initial config:`, storedData);
            setSocketAddr(storedData.socketAddr || "ws://localhost:8080"); // Fallback if addr is null/undefined
            initialMarketNames.current = storedData.marketList?.map(m => m.name) || [];
            setMarketList(initialMarketNames.current.map(name => ({ name, files: [] })));
        } else {
            console.warn(`[${STORE_NAMESPACE}] No initial config found in store2.`);
            setMarketList([]);
            initialMarketNames.current = [];
        }
        setIsLoading(false);
    }, []);

    // 2. Manage WebSocket connection and communication
    useEffect(() => {
        if (!socketAddr) {
            console.log(`[${STORE_NAMESPACE}] No socket address.`);
            setIsConnected(false);
            return;
        }

        if (ws.current) {
            ws.current!.close();
        }

        console.log(`[${STORE_NAMESPACE}] Attempting to connect: ${socketAddr}`);
        ws.current = new WebSocket(socketAddr);
        setIsConnected(false);

        ws.current!.onopen = () => {
            console.log(`[${STORE_NAMESPACE}] WebSocket connected.`);
            setIsConnected(true);
            // 3. Request ALL market data from the server
            if (ws.current?.readyState === WebSocket.OPEN) {
                console.log(`[${STORE_NAMESPACE}] Requesting all market data from server.`);
                const request = JSON.stringify({ action: 'getAllMarkets' });
                ws.current.send(request);
            } else {
                console.warn(`[${STORE_NAMESPACE}] WebSocket not open when trying to send getAllMarkets request.`);
            }
        };

        ws.current.onmessage = (event) => {
            try {
                const message = JSON.parse(event.data.toString());
                console.log(`[${STORE_NAMESPACE}] Received:`, message.type, message.marketName || '');

                setMarketList(currentList => {
                    // Use structuredClone for safe deep copy and modification
                    let updatedList = structuredClone(currentList);

                    // Handle response containing all market data
                    if (message.type === 'allMarketData' && Array.isArray(message.markets)) {
                        console.log(`[${STORE_NAMESPACE}] Received all market data. Replacing local list.`);
                        // Replace the entire list with the data from the server
                        updatedList = message.markets.map((m: any) => ({
                            name: m.name,
                            files: m.files?.map((f: any) => ({ ...f, content: f.content || '' })) || [],
                            html: m.html
                        }));
                    } else if (message.type === 'marketData' && message.marketName) {
                        const marketIdx = updatedList.findIndex(m => m.name === message.marketName);
                        if (marketIdx !== -1) {
                            updatedList[marketIdx].files = message.files?.map((f: any) => ({ ...f, content: f.content || '' })) || []; // Ensure content is string
                            updatedList[marketIdx].html = message.html;
                        } else {
                            // If server sent data for a market we didn't know about (e.g., from getAllMarkets), add it
                            console.log(`[${STORE_NAMESPACE}] Received marketData for a new market: ${message.marketName}. Adding to list.`);
                            updatedList.push({
                                name: message.marketName,
                                files: message.files?.map((f: any) => ({ ...f, content: f.content || '' })) || [],
                                html: message.html
                            });
                            // Sort alphabetically? (Optional)
                            // updatedList.sort((a, b) => a.name.localeCompare(b.name));
                        }
                    } else if (message.type === 'fileUpdate' && message.marketName && message.path) {
                        const marketIdx = updatedList.findIndex(m => m.name === message.marketName);
                        if (marketIdx !== -1) {
                            const fileIdx = updatedList[marketIdx].files.findIndex(f => f.path === message.path);
                            if (fileIdx !== -1) {
                                updatedList[marketIdx].files[fileIdx].content = message.content || ''; // Ensure content is string
                                updatedList[marketIdx].files[fileIdx].type = message.fileType;
                            } else {
                                console.warn(`[${STORE_NAMESPACE}] FileUpdate for unknown file: ${message.marketName}/${message.path}`);
                                // Optionally add the file if it didn't exist in the initial marketData
                                // updatedList[marketIdx].files.push({ type: message.fileType, path: message.path, content: message.content || '' });
                            }
                        } else {
                             console.warn(`[${STORE_NAMESPACE}] FileUpdate for unknown market: ${message.marketName}`);
                        }
                    } else if (message.type === 'error') {
                         console.error(`[${STORE_NAMESPACE}] Server error:`, message.message);
                         // TODO: Show error feedback (e.g., Snackbar)
                    } else {
                         console.log(`[${STORE_NAMESPACE}] Unhandled message type:`, message.type);
                    }
                    return updatedList;
                });

            } catch (error) {
                console.error(`[${STORE_NAMESPACE}] Error processing message:`, error, event.data);
            }
        };

        ws.current.onerror = (error) => {
            console.error(`[${STORE_NAMESPACE}] WebSocket error:`, error);
            setIsConnected(false);
        };

        ws.current.onclose = (event) => {
            console.log(`[${STORE_NAMESPACE}] WebSocket disconnected. Code: ${event.code}, Reason: ${event.reason}`);
            setIsConnected(false);
            // Decide if you want to clear data or show stale
            // setMarketList(current => current.map(m => ({...m, files: m.files.map(f => ({...f, content: '(Disconnected)'})) })));
        };

        // Cleanup
        return () => {
            if (ws.current) {
                console.log(`[${STORE_NAMESPACE}] Closing WebSocket on unmount.`);
                ws.current.onopen = null;
                ws.current.onmessage = null;
                ws.current.onerror = null;
                ws.current.onclose = null;
                ws.current.close();
                ws.current = null;
            }
        };
    }, [socketAddr]);

    return (
        <Container maxWidth="md" sx={{ py: 3 }}>
            <Typography variant="h5" gutterBottom component="div">
                Market Watcher Status
            </Typography>
            <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                 <Chip
                     label={isConnected ? 'Connected' : (socketAddr ? 'Connecting...' : 'Disconnected')}
                     color={isConnected ? 'success' : (socketAddr ? 'warning' : 'error')}
                     size="small"
                     sx={{ mr: 2 }}
                 />
                 <Typography variant="body2" color="textSecondary">
                     {socketAddr || 'No address configured'}
                 </Typography>
            </Box>
            <Divider sx={{ mb: 2 }}/>

            <Typography variant="h6" gutterBottom component="div">
                 Watched Markets
            </Typography>
            {/* Pass loading=true only if we are loading initial config AND have no markets yet */} 
            <MarketListDisplay marketList={marketList} isLoading={isLoading && marketList.length === 0} />
        </Container>
    );
}